parameters.jsCode:
// Aggregate all campaigns for the current client and build an HTML report
const client = $('Loop Over Clients').item.json;
const rows = $input.all().map(i => i.json).filter(j => j && j['Campaign Name']);

let emailsSent = 0, replies = 0, positive = 0, meetings = 0, bounces = 0;
let campaignRows = '';

for (const j of rows) {
  const es = Number(j['Emails Sent']) || 0;
  const rp = Number(j['Replies']) || 0;
  const pr = Number(j['Positive Replies']) || 0;
  const mt = Number(j['Meetings']) || 0;
  const bo = Number(j['Bounces']) || 0;
  emailsSent += es; replies += rp; positive += pr; meetings += mt; bounces += bo;
  const rr = es ? ((rp / es) * 100).toFixed(1) : '0.0';
  const br = es ? ((bo / es) * 100).toFixed(1) : '0.0';
  const td = 'padding:6px 10px;border:1px solid #ddd;';
  const tdr = td + 'text-align:right;';
  campaignRows += '<tr>' +
    '<td style="' + td + '">' + (j['Campaign Name'] || '') + '</td>' +
    '<td style="' + tdr + '">' + es + '</td>' +
    '<td style="' + tdr + '">' + rp + '</td>' +
    '<td style="' + tdr + '">' + pr + '</td>' +
    '<td style="' + tdr + '">' + mt + '</td>' +
    '<td style="' + tdr + '">' + rr + '%</td>' +
    '<td style="' + tdr + '">' + br + '%</td>' +
    '</tr>';
}

const replyRate = emailsSent ? ((replies / emailsSent) * 100).toFixed(1) : '0.0';
const bounceRate = emailsSent ? ((bounces / emailsSent) * 100).toFixed(1) : '0.0';
const positiveRate = emailsSent ? ((positive / emailsSent) * 100).toFixed(1) : '0.0';
const clientName = client['Client Name'] || 'Client';
const reportDate = new Date().toISOString().slice(0, 10);

if (!campaignRows) {
  campaignRows = '<tr><td colspan="7" style="padding:10px;border:1px solid #ddd;text-align:center;color:#888;">No campaigns found for this client.</td></tr>';
}

const th = 'padding:8px 10px;border:1px solid #ddd;background:#f4f4f4;text-align:left;';
const thr = th + 'text-align:right;';
const card = 'display:inline-block;min-width:120px;margin:4px;padding:12px 16px;border:1px solid #e0e0e0;border-radius:6px;';
const cardNum = 'font-size:22px;font-weight:bold;color:#1a73e8;';
const cardLbl = 'font-size:12px;color:#666;text-transform:uppercase;';

const html =
'<div style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:760px;">' +
  '<h2 style="margin-bottom:4px;">Weekly Campaign Report — ' + clientName + '</h2>' +
  '<p style="color:#666;margin-top:0;">Generated ' + reportDate + '</p>' +
  '<div style="margin:16px 0;">' +
    '<div style="' + card + '"><div style="' + cardNum + '">' + emailsSent + '</div><div style="' + cardLbl + '">Emails Sent</div></div>' +
    '<div style="' + card + '"><div style="' + cardNum + '">' + replies + '</div><div style="' + cardLbl + '">Replies</div></div>' +
    '<div style="' + card + '"><div style="' + cardNum + '">' + positive + '</div><div style="' + cardLbl + '">Positive Replies</div></div>' +
    '<div style="' + card + '"><div style="' + cardNum + '">' + meetings + '</div><div style="' + cardLbl + '">Meetings</div></div>' +
    '<div style="' + card + '"><div style="' + cardNum + '">' + replyRate + '%</div><div style="' + cardLbl + '">Reply Rate</div></div>' +
    '<div style="' + card + '"><div style="' + cardNum + '">' + bounceRate + '%</div><div style="' + cardLbl + '">Bounce Rate</div></div>' +
  '</div>' +
  '<h3>Per-Campaign Breakdown</h3>' +
  '<table style="border-collapse:collapse;width:100%;font-size:14px;">' +
    '<thead><tr>' +
      '<th style="' + th + '">Campaign</th>' +
      '<th style="' + thr + '">Sent</th>' +
      '<th style="' + thr + '">Replies</th>' +
      '<th style="' + thr + '">Positive</th>' +
      '<th style="' + thr + '">Meetings</th>' +
      '<th style="' + thr + '">Reply %</th>' +
      '<th style="' + thr + '">Bounce %</th>' +
    '</tr></thead>' +
    '<tbody>' + campaignRows + '</tbody>' +
  '</table>' +
'</div>';

return [{ json: {
  clientId: client.id,
  clientName,
  recipient: client['Weekly Report Recipient'],
  emailsSent, replies, positive, meetings, bounces,
  replyRate, bounceRate, positiveRate,
  html,
} }];

// One campaign per loop iteration (batchSize = 1)
const stats = $input.first().json;
const campaign = $('Loop Over Campaigns').item.json;
const client = $('Get Campaign Client').item.json;

const emailsSent = Number(stats.emails_sent_count) || 0;
const replies = Number(stats.reply_count) || 0;
const bounces = Number(stats.bounced_count) || 0;
const positive = Number(stats.total_interested) || 0;
const meetings = Number(stats.total_meeting_booked) || 0;

// Rates as decimals (Airtable percent fields store decimals, e.g. 0.03 = 3%)
const replyRate = emailsSent ? replies / emailsSent : 0;
const bounceRate = emailsSent ? bounces / emailsSent : 0;

// Thresholds from the linked Client (percent -> decimal). Sensible fallbacks.
const minReplyRate = (client['Minimum Reply Rate'] != null) ? Number(client['Minimum Reply Rate']) : 0.02;
const maxBounceRate = (client['Maximum Bounce Rate'] != null) ? Number(client['Maximum Bounce Rate']) : 0.05;

const lowReply = replyRate < minReplyRate;
const highBounce = bounceRate > maxBounceRate;
const needsAttention = lowReply || highBounce;

const reasons = [];
if (lowReply) reasons.push('Reply rate ' + (replyRate * 100).toFixed(1) + '% is below the minimum ' + (minReplyRate * 100).toFixed(1) + '%');
if (highBounce) reasons.push('Bounce rate ' + (bounceRate * 100).toFixed(1) + '% is above the maximum ' + (maxBounceRate * 100).toFixed(1) + '%');

const campaignName = campaign['Campaign Name'] || stats.campaign_name || 'Campaign';
const clientName = client['Client Name'] || '';
const managerEmail = client['Sales Rep Email'] || '';
const managerName = client['Assigned Sales Rep'] || 'there';

const li = 'margin:4px 0;';
const html =
'<div style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:640px;">' +
  '<h2 style="color:#c0392b;margin-bottom:4px;">Campaign Needs Attention</h2>' +
  '<p style="margin-top:0;">Hi ' + managerName + ', the following campaign has crossed a health threshold.</p>' +
  '<p><strong>Client:</strong> ' + clientName + '<br/>' +
  '<strong>Campaign:</strong> ' + campaignName + '</p>' +
  '<ul>' +
    '<li style="' + li + '">Emails Sent: ' + emailsSent + '</li>' +
    '<li style="' + li + '">Replies: ' + replies + ' (' + (replyRate * 100).toFixed(1) + '%)</li>' +
    '<li style="' + li + '">Bounces: ' + bounces + ' (' + (bounceRate * 100).toFixed(1) + '%)</li>' +
    '<li style="' + li + '">Meetings Booked: ' + meetings + '</li>' +
  '</ul>' +
  '<p style="color:#c0392b;"><strong>Why:</strong></p>' +
  '<ul>' + reasons.map(r => '<li style="' + li + '">' + r + '</li>').join('') + '</ul>' +
'</div>';

return [{ json: {
  campaignId: campaign.id,
  campaignName,
  clientName,
  managerEmail,
  emailsSent, replies, bounces, positive, meetings,
  replyRatePct: (replyRate * 100).toFixed(1),
  bounceRatePct: (bounceRate * 100).toFixed(1),
  needsAttention,
  reasonsText: reasons.join('; '),
  html,
} }];
